) s
ON (t.INSTITUTION_ID = s.INSTITUTION_ID)
WHEN MATCHED THEN UPDATE SET
    t.ORG_CODE  = COALESCE(t.ORG_CODE,  s.ORG_CODE),
    t.G2B_CODE  = COALESCE(t.G2B_CODE,  s.G2B_CODE),
    t.OPEN_DATE = COALESCE(t.OPEN_DATE, s.OPEN_DATE),
    t.OP_STATUS = CASE WHEN t.OP_SRC_URL IS NULL AND t.OP_SRC_NO IS NULL THEN s.OP_STATUS ELSE t.OP_STATUS END,
    t.CONTRACT_END_SRC_URL = CASE WHEN t.CONTRACT_END = s.CONTRACT_END AND t.CONTRACT_END_CONFIRMED = 0 THEN COALESCE(t.CONTRACT_END_SRC_URL, s.CONTRACT_END_SRC_URL) ELSE t.CONTRACT_END_SRC_URL END,
    t.CONTRACT_END_SRC_NO  = CASE WHEN t.CONTRACT_END = s.CONTRACT_END AND t.CONTRACT_END_CONFIRMED = 0 THEN COALESCE(t.CONTRACT_END_SRC_NO,  s.CONTRACT_END_SRC_NO)  ELSE t.CONTRACT_END_SRC_NO  END,
    t.CONTRACT_END_CONFIRMED = CASE WHEN t.CONTRACT_END = s.CONTRACT_END AND t.CONTRACT_END_CONFIRMED = 0 THEN s.CONTRACT_END_CONFIRMED ELSE t.CONTRACT_END_CONFIRMED END
WHEN NOT MATCHED THEN INSERT
    (INSTITUTION_ID, NAME_KO, REGION_CODE, TYPE, CONTRACT_END, LAST_BID, TERM, STAGE, ORG_CODE, G2B_CODE, OP_STATUS, OPEN_DATE, CONTRACT_END_CONFIRMED, CONTRACT_END_SRC_URL, CONTRACT_END_SRC_NO)
VALUES
    (s.INSTITUTION_ID, s.NAME_KO, s.REGION_CODE, s.TYPE, s.CONTRACT_END, s.LAST_BID, s.TERM, 1, s.ORG_CODE, s.G2B_CODE, s.OP_STATUS, s.OPEN_DATE, s.CONTRACT_END_CONFIRMED, s.CONTRACT_END_SRC_URL, s.CONTRACT_END_SRC_NO);

COMMIT;
